    # Filter out characters from s that are present in c
    s_prime = ''.join([char for char in s if char not in c])

    # Check if the reversed version of s_prime is equal to s_prime itself
    if s_prime == s_prime[::-1]:
        return (s_prime, True)
    else:
        return (s_prime, False)

